#!/usr/bin/env python3
"""Script to verify the self-signed TLS certificate."""

import os
import sys
from datetime import datetime

CERT_PATH = "/app/ssl/server.crt"


def check_cert_exists():
    """Verify that the certificate file exists."""
    if not os.path.exists(CERT_PATH):
        print(f"ERROR: Certificate file not found at {CERT_PATH}")
        return False
    print(f"Certificate file found: {CERT_PATH}")
    return True


def load_certificate():
    """Load the certificate using OpenSSL via subprocess."""
    import subprocess

    try:
        result = subprocess.run(
            ["openssl", "x509", "-in", CERT_PATH, "-noout", "-text"],
            capture_output=True,
            text=True,
            check=True,
        )
        return result.stdout
    except subprocess.CalledProcessError as e:
        print(f"ERROR: Failed to load certificate: {e.stderr}")
        return None


def extract_field(cert_text, field_name):
    """Extract a field value from the certificate text output."""
    for line in cert_text.splitlines():
        if field_name in line:
            return line.split(":", 1)[1].strip()
    return None


def get_common_name(cert_text):
    """Extract the Common Name from the certificate."""
    for line in cert_text.splitlines():
        if "Subject:" in line:
            # Parse the Subject line for CN
            parts = line.split("Subject:")[1].strip()
            for part in parts.split("/"):
                if part.strip().startswith("CN"):
                    return part.split("=", 1)[1].strip()
    return None


def get_expiration_date(cert_text):
    """Extract and format the expiration date as YYYY-MM-DD."""
    for line in cert_text.splitlines():
        if "Not After" in line:
            date_str = line.split("Not After")[1].strip()
            # Parse the date string (e.g., "Aug 11 00:32:20 2027 GMT")
            dt = datetime.strptime(date_str, "%b %d %H:%M:%S %Y %Z")
            return dt.strftime("%Y-%m-%d")
    return None


def main():
    # Step 1: Verify certificate exists
    if not check_cert_exists():
        sys.exit(1)

    # Step 2: Load the certificate
    cert_text = load_certificate()
    if cert_text is None:
        print("ERROR: Could not load certificate.")
        sys.exit(1)

    print("Certificate loaded successfully.")

    # Step 3: Extract and print certificate details
    common_name = get_common_name(cert_text)
    expiration_date = get_expiration_date(cert_text)

    if common_name:
        print(f"Common Name: {common_name}")
    else:
        print("WARNING: Could not extract Common Name.")

    if expiration_date:
        print(f"Expiration Date: {expiration_date}")
    else:
        print("WARNING: Could not extract expiration date.")

    # Step 4: Verify the certificate is valid (not expired)
    if expiration_date:
        exp_date = datetime.strptime(expiration_date, "%Y-%m-%d")
        if exp_date < datetime.now():
            print("ERROR: Certificate has expired.")
            sys.exit(1)

    print("Certificate verification successful")


if __name__ == "__main__":
    main()

